withLabelsCode.web:
// A palavra de cada um dos cinco estados, e o rótulo da ação onde ela existe.
//
// Em espera e concluída ficam sem ação de propósito: começar uma execução é do
// campo de mensagem, e sobre uma resposta pronta não há o que fazer aqui.
const rotulos = {
  status: {
    idle: 'Em espera',
    running: 'Respondendo',
    stopped: 'Interrompida',
    complete: 'Concluída',
    failed: 'Falhou',
  },
  action: {
    running: 'Parar',
    stopped: 'Retomar',
    failed: 'Tentar de novo',
  },
};

extensibilityCode.web:
// A INTENÇÃO sai do vocabulário compartilhado, e não de um `if` da tela:
// enquanto a execução não terminou, a ação INTERROMPE; depois de terminada,
// ela COMEÇA DE NOVO.
isRunFinished('running');  // false → a ação pede 'stop'
isRunFinished('stopped');  // true  → a ação pede 'start'
isRunFinished('failed');   // true  → a ação pede 'start'

// O que "começar de novo" significa — retomar de onde parou ou refazer do
// zero — é decisão de produto. A peça não executa nada.

customizationCode.web:
.nds-agent-status {
  max-inline-size: 32rem;
}

/* O ponto é REFORÇO, e não a pista: a palavra ao lado é o que descreve o
   estado. Mexer no ponto não muda o que chega a quem ouve. */
.nds-agent-status[data-status="running"] .nds-agent-status-dot {
  animation: nds-thinking-pulse var(--duration-slow) var(--ease-standard) infinite;
}

