// The word for each of the five states, and the action label where one exists.
//
// Idle and done are left without an action on purpose: starting a run belongs
// to the message field, and there is nothing to do here about a finished answer.
const rotulos = {
  status: {
    idle: 'Idle',
    running: 'Answering',
    stopped: 'Stopped',
    complete: 'Done',
    failed: 'Failed',
  },
  action: {
    running: 'Stop',
    stopped: 'Resume',
    failed: 'Try again',
  },
};

extensibilityCode.web:
// The INTENT comes from the shared vocabulary, not from an `if` on screen:
// while the run has not finished, the action INTERRUPTS; once it has finished,
// it STARTS OVER.
isRunFinished('running');  // false → the action asks for 'stop'
isRunFinished('stopped');  // true  → the action asks for 'start'
isRunFinished('failed');   // true  → the action asks for 'start'

// What "start over" means — resume where it stopped, or redo from scratch —
// is a product decision. The piece runs nothing.

